def adelante(apps, schema_editor):
    """Los 4 sectores de GERP quedan aprobados tal como están. Las tarjetas que GEMA publica hoy en
    «¿Para quién es GEMA?» pasan a ser sus sectores (aprobados, mismo texto). GEAGRO: dos sectores en
    borrador, sin textos comerciales y sin tarjeta (su web no tiene esa sección)."""
    from contenidos.sectores import GEAGRO, GEMA
    Sector = apps.get_model("contenidos", "Sector")
    SitioWeb = apps.get_model("sitios", "SitioWeb")
    Linea = apps.get_model("sitios", "LineaProducto")
    for s in Sector.objects.filter(nombre=""):
        s.nombre = s.titulo
        s.save(update_fields=["nombre"])
    gema = SitioWeb.objects.filter(clave="gema").first()
    if gema and not Sector.objects.filter(sitio=gema).exists():
        for i, x in enumerate(GEMA, 1):
            Sector.objects.create(sitio=gema, orden=i, live=True, **x)
    geagro = SitioWeb.objects.filter(clave="geagro").first()
    if geagro and not Sector.objects.filter(sitio=geagro).exists():
        for i, x in enumerate(GEAGRO, 1):
            x = dict(x)
            linea = Linea.objects.filter(sitio=geagro, clave=x.pop("linea")).first()
            Sector.objects.create(sitio=geagro, linea=linea, orden=i, live=False, has_unpublished_changes=True,
                                  mostrar_tarjeta=False, visible=False, **x)
    ContentType = apps.get_model("contenttypes", "ContentType")
    Workflow = apps.get_model("wagtailcore", "Workflow")
    WorkflowContentType = apps.get_model("wagtailcore", "WorkflowContentType")
    wf = Workflow.objects.filter(active=True).first()
    if wf:
        ct, _ = ContentType.objects.get_or_create(app_label="contenidos", model="sector")
        WorkflowContentType.objects.get_or_create(content_type=ct, defaults={"workflow": wf})


